from scipy.optimize import least_squares
def run(model, p0s):
    best=None
    for p0 in p0s:
        try:
            r=least_squares(lambda p: model(p)-dv_dt, p0, max_nfev=4000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return np.mean(best.fun**2)/np.var(dv_dt), np.round(best.x,4)
